import React from 'react';
import '../styles/aboutus.css';

function AboutUs() {
  return (
    <div className="about">
      <h2>About WE4HIM</h2>
      <p>WE4HIM CBO was established to empower boys and men in Migori County through social, political, and economic inclusion.</p>
      <p>Founded in 2012, officially registered in 2024, and governed by a committed Board of Management.</p>
    </div>
  );
}

export default AboutUs;
